#!/bin/sh
# hypha satellite installer.
# Generated by the hub; the token below is single-use and expires.
#
#   curl -fsSL <hub>/install.sh?token=xxx | sudo sh
#
set -eu

HUB="__HUB__"
TOKEN="__TOKEN__"

PREFIX="${HYPHA_PREFIX:-/usr/local/bin}"
CONF_DIR="${HYPHA_CONF_DIR:-/etc/hypha}"
SVC_NAME="hypha-sat"

say() { printf '\033[36m[hypha]\033[0m %s\n' "$*"; }
die() { printf '\033[31m[hypha] %s\033[0m\n' "$*" >&2; exit 1; }

[ "$(id -u)" = "0" ] || die "must run as root (sudo)"

case "$(uname -s)" in
    Linux)  OS=linux ;;
    Darwin) OS=darwin ;;
    *) die "unsupported OS: $(uname -s)" ;;
esac

case "$(uname -m)" in
    x86_64|amd64)  ARCH=x86_64 ;;
    aarch64|arm64) ARCH=aarch64 ;;
    *) die "unsupported arch: $(uname -m)" ;;
esac

ARCHIVE="hypha-sat-${OS}-${ARCH}"
say "installing ${ARCHIVE} from ${HUB}"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

if command -v curl >/dev/null 2>&1; then
    curl -fsSL "${HUB}/dl/${ARCHIVE}" -o "$TMP/hypha-sat" || die "download failed"
elif command -v wget >/dev/null 2>&1; then
    wget -q "${HUB}/dl/${ARCHIVE}" -O "$TMP/hypha-sat" || die "download failed"
else
    die "need curl or wget"
fi

install -D -m 0755 "$TMP/hypha-sat" "${PREFIX}/hypha-sat"
mkdir -p "$CONF_DIR"

say "enrolling with token ${TOKEN}"
"${PREFIX}/hypha-sat" --config "${CONF_DIR}/agent.json" enroll --hub "$HUB" --token "$TOKEN" \
    || die "enrollment failed (token expired or already used?)"

if [ "$OS" = "linux" ] && [ -d /run/systemd/system ]; then
    say "installing systemd service"
    cat > "/etc/systemd/system/${SVC_NAME}.service" <<EOF
[Unit]
Description=hypha satellite
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=${PREFIX}/hypha-sat --config ${CONF_DIR}/agent.json run
Restart=always
RestartSec=2
# The agent is root by design: it is your hands on this box.
User=root
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload
    systemctl enable --now "$SVC_NAME"
    sleep 1
    systemctl is-active --quiet "$SVC_NAME" || die "service failed to start: journalctl -u $SVC_NAME"
else
    say "starting in background (no systemd detected)"
    nohup "${PREFIX}/hypha-sat" --config "${CONF_DIR}/agent.json" run \
        >> "${CONF_DIR}/agent.log" 2>&1 &
fi

say "done. this machine should appear in your panel within a second."
